import { Button } from "../Button";
import { Icon } from "../Icon";
import { StyleFn } from "..";

export const IconButton: StyleFn = (theme, mode) => {
  const {
    size: { spacing },
  } = theme;
  const {
    root: buttonRoot,
    _ghost,
    _ghostNegative,
    _primary,
    _secondary,
    _success,
    _warning,
    _error,
  } = Button(theme, mode);
  const {
    root: iconRoot,
    _xsmall: iconXS,
    _small: iconS,
    _large: iconL,
    _xlarge: iconXL,
  } = Icon(theme, mode);

  return {
    root: {
      ...buttonRoot,
      minWidth: spacing[40],
      padding: spacing[6],
      "& svg, & i": iconRoot,
    },
    _ghost,
    _ghostNegative,
    _primary,
    _secondary,
    _success,
    _warning,
    _error,
    _xsmall: {
      minWidth: spacing[24],
      minHeight: spacing[24],
      padding: spacing[2],
      "& svg, & i": iconXS,
    },
    _small: {
      minWidth: spacing[32],
      minHeight: spacing[32],
      padding: spacing[4],
      "& svg, & i": iconS,
    },
    _medium: {},
    _large: {
      minWidth: spacing[48],
      minHeight: spacing[48],
      padding: spacing[6],
      "& svg, & i": iconL,
    },
    _xlarge: {
      minWidth: spacing[56],
      minHeight: spacing[56],
      padding: spacing[6],
      "& svg, & i": iconXL,
    },
  };
};
